{
	"name": "opencode-bash-frisk",
	"version": "0.1.3",
	"description": "Skip the permission prompt for shell commands that are provably read-only, and explain the ones that remain",
	"homepage": "https://github.com/j-chad/bash-frisk/tree/main/adapters/opencode",
	"bugs": "https://github.com/j-chad/bash-frisk/issues",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/j-chad/bash-frisk.git",
		"directory": "adapters/opencode"
	},
	"license": "MIT",
	"author": "j-chad",
	"engines": {
		"bun": "^1.3.0"
	},
	"keywords": [
		"opencode",
		"opencode-plugin",
		"bash",
		"permissions",
		"security",
		"agent"
	],
	"type": "module",
	"exports": {
		".": "./dist/index.js",
		"./server": "./dist/index.js"
	},
	"main": "./dist/index.js",
	"files": [
		"dist"
	],
	"scripts": {
		"build": "bun build ./src/index.ts --outdir ./dist --target bun --external @opencode-ai/plugin",
		"typecheck": "tsc --noEmit",
		"publish": "bun run typecheck && bun run build && bun publish"
	},
	"devDependencies": {
		"@types/bun": "^1.3.14",
		"typescript": "^7.0.2",
		"@opencode-ai/plugin": "^1.18.16"
	}
}
